    if c <= 0.0031308: return 12.92 * c
    return 1.055 * (c ** (1.0 / 2.4)) - 0.055
def to_hex(rgb):
    return "#" + "".join(f"{max(0, min(255, round(lin_to_srgb(c)*255))):02x}" for c in rgb)

ir = json.load(open("/tmp/containment_gate_ir.json"))
for m in ir["materials"]:
    print(m["id"], "base_hex:", to_hex(m["base_color"]), "metallic:", m["metallic"], "roughness:", m["roughness"], "surface:", repr(m["surface"]))
print("mat_cobalt emissive_hex:", to_hex([0.01850022003054619, 0.12477181851863861, 0.8307698965072632]))
'

